target.css:
:root {
  --ink: #183640;
  --muted: #63808a;
  --panel: #fffefa;
  --line: #d7e5e4;
  --aqua: #197f86;
  --aqua-soft: #e2f3f1;
  --coral: #c55b48;
  --coral-soft: #fbe9e4;
  --deep: #123e49;
}

.fountain-card {
  box-sizing: border-box;
  width: 480px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--panel);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.title-group {
  display: flex;
  align-items: baseline;
  gap: 9px;
}

.eyebrow,
.section-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.title-group h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.live-badge {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--aqua-soft);
  color: var(--aqua);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.flow-strip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 10px;
  background: var(--deep);
  color: var(--panel);
  font-size: 12px;
}

.flow-icon {
  color: var(--aqua-soft);
  font-size: 22px;
  line-height: 12px;
}

.flow-strip p {
  flex: 1;
  margin: 0;
}

.flow-strip strong {
  color: var(--aqua-soft);
}

.time-stamp {
  color: var(--line);
  font-size: 10px;
}

.metric-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin: 10px 0;
}

.metric {
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--panel);
}

.metric span,
.metric small {
  display: block;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.2;
}

.metric strong {
  display: block;
  margin: 4px 0 2px;
  color: var(--deep);
  font-size: 18px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.metric.warning {
  border-color: var(--coral);
  background: var(--coral-soft);
}

.metric.warning strong {
  color: var(--coral);
}

.work-area {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 10px;
  border-radius: 11px;
  background: var(--aqua-soft);
}

.task-block {
  display: grid;
  gap: 3px;
}

.task-name {
  margin: 0;
  font-size: 13px;
  font-weight: 750;
}

.task-detail {
  color: var(--muted);
  font-size: 10px;
}

.progress-block {
  display: grid;
  justify-items: end;
  gap: 6px;
  color: var(--aqua);
  font-size: 10px;
  font-weight: 800;
}

.progress-track {
  display: block;
  width: 74px;
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--panel);
}

.progress-track i {
  display: block;
  width: 67%;
  height: 100%;
  border-radius: inherit;
  background: var(--aqua);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 10px;
}

.crew {
  color: var(--muted);
  font-size: 11px;
}

.crew b {
  margin-right: 3px;
  color: var(--deep);
}

.card-footer button {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 7px 10px;
  border: 0;
  border-radius: 8px;
  background: var(--aqua);
  color: var(--panel);
  font-size: 11px;
  font-weight: 800;
}

.card-footer button span {
  font-size: 15px;
  line-height: 10px;
}

